"""Independent agreement components; annotation revisions do not erase placement evidence."""
import json,sys
from pathlib import Path

def compare(packet,reply):
 prior={a['i']:a for a in packet.get('priorAssignments',[]) if 'q' in a};supported={a['id'] for a in reply['cardReviews'] if a['decision']=='supported_as_written' and a['scopeChange']=='same'};priorf={f['id']:f for f in packet.get('priorFactors',[])};newf={f['id']:f for f in reply['factors']};factors={**priorf,**newf};out=[]
 for row in reply['units']:
  old=prior.get(row['i']);oldq={(q['id'],q['role']) for q in old['q']} if old else set();newq={(q['id'],q['role']) for q in row['q']};common=oldq&newq;disposition_equal=old is not None and old['d']==row['d'];oldf=set(old['f']) if old else set();newfs=set(row['f']);material_flag=row['reason'] in ['changed_regime','scope_mismatch']
  contributions=[{'questionRef':q,'role':role,'independentRoleAgreement':True,'scopeSupportedUnchanged':q in supported,'dispositionAgreement':disposition_equal,'admissionBasis':'same_scoped_question_and_typed_role','requiresSubstantiveScopeAdjudication':material_flag,'factorAgreementNotImplied':True,'fineEquivalenceNotImplied':True} for q,role in sorted(common)]
  out.append({'unitIndex':row['i'],'priorAvailable':old is not None,'declaredAgreement':row['a'],'exactContributionAgreements':contributions,'addedContributions':[{'questionRef':q,'role':role} for q,role in sorted(newq-oldq)],'removedContributions':[{'questionRef':q,'role':role} for q,role in sorted(oldq-newq)],'broadDisposition':{'old':old['d'] if old else None,'new':row['d'],'agrees':disposition_equal,'scopeSupportedUnchanged':'r' in supported,'candidateForAcceptedPlacement':disposition_equal and 'r' in supported and row['d'] in ['member','overlap'] and not material_flag},'factorChanges':{'added':[{'id':f,**factors[f]} for f in sorted(newfs-oldf)],'removed':[{'id':f,**priorf[f]} for f in sorted(oldf-newfs)],'sameAssignmentIds':old is not None and oldf==newfs,'scientificPremiseAgreementInferred':False},'fineIdentity':{'old':old['identity'] if old else None,'new':row['identity'],'sameState':old is not None and old['identity']==row['identity'],'canonicalUniquenessCertified':False},'scopeReviewReason':row['reason'],'note':row['note']})
 return {'schemaVersion':'q025-independent-agreement-components/1','familyId':packet['familyId'],'units':out,'counts':{'exactTypedContributionAgreements':sum(len(x['exactContributionAgreements']) for x in out),'broadPlacementCandidates':sum(x['broadDisposition']['candidateForAcceptedPlacement'] for x in out),'factorAssignmentChanges':sum(not x['factorChanges']['sameAssignmentIds'] for x in out),'fineStateChanges':sum(not x['fineIdentity']['sameState'] for x in out)},'admission':'Evidence components only. Scope/placement receipts bind accepted final content; changed-target/regime flags require substantive review, and no alias follows from a source singleton.'}
if __name__=='__main__':
 p=json.loads(Path(sys.argv[1]).read_text());r=json.loads(Path(sys.argv[2]).read_text());out=compare(p,r);Path(sys.argv[3]).write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n');print(json.dumps(out['counts']))
